const m = $json;                   // adjust keys to your trigger payload
const phone = m.from || m.contacts?.[0]?.wa_id || m.message?.from || '';
const chatId = m.chat?.id || m.conversation?.id || m.context?.id || '';
const messageId = m.id || m.message?.id || m.messages?.[0]?.id || '';
const text = m.text?.body || m.message?.text || m.body || '';
const msgType = m.type || 'text';
const ts = m.timestamp ? new Date(Number(m.timestamp)*1000) : new Date();

return [{
  platform: 'whatsapp',
  phone_e164: phone,
  chat_id: chatId,
  message_id: messageId,
  text,
  message_type: msgType,
  ts_iso: ts.toISOString(),
  direction: 'inbound',
  role: 'user'
}];
